import{_ as s,l as o,o as e,c as p,v as t,p as i,x as r,d as E,i as n,S as h}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"Epps 效应","description":"","frontmatter":{"title":"Epps 效应","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/epps-effect.md","filePath":"quant/epps-effect.md","lastUpdated":1789023840000}'),d={name:"quant/epps-effect.md"};function c(A,a,B,m,D,u){const l=o("Mermaid");return e(),p("div",null,[a[1]||(a[1]=t('<h1 id="epps-效应" tabindex="-1">Epps 效应 <a class="header-anchor" href="#epps-效应" aria-label="Permalink to &quot;Epps 效应&quot;">​</a></h1><div class="epigraph"><p>股票收益的样本相关会随采样间隔缩短而下降：日频上还清楚的同向运动，到了数分钟或数秒，相关系数往往只剩下一个更小的数。</p><footer>—— Epps, Comovements in Stock Prices in the Very Short Run, Journal of the American Statistical Association, 1979</footer></div><p>Epps（1979）在纽交所股票上记录：把间隔从几天收到几分钟，样本相关系统性变小。这不是一条需要「交易」的异常收益，而是高频协方差估计的签名：若把分钟相关直接当成经济上的瞬时相关去配期权、去算盘中 \\(\\beta\\)、去写风险预算，会系统性<strong>低配共同因子、高配特异残差</strong>。本篇把效应拆成不同步、微观结构噪声、领先滞后与离散报价四块，并指向 <a href="/quant/hayashi-yoshida">Hayashi–Yoshida</a> 与 <a href="/quant/realized-kernel">已实现核</a> 各修哪一块。它与 <a href="/quant/ou-spread">OU 价差</a> 的关系是频率匹配：在被 Epps 压低的相关上估对冲比，等于把共同波动藏进残差的「alpha」。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>记间隔 \\(\\Delta\\) 上的收益相关 \\(\\rho(\\Delta)\\)。经验上 \\(\\rho(\\Delta)\\) 随 \\(\\Delta\\downarrow\\) 下降，签名图的多元版是：横轴采样频率，纵轴已实现相关，高频端向下弯。若真实瞬时相关是某个 \\(\\rho_*\\)（由连续共变差定义），朴素同步估计在 \\(\\Delta\\) 太小时不是 \\(\\rho_*\\) 的好估计。问题有两层。估计层：用哪一个 \\(\\Delta\\) 或哪一个估计量才能回到 \\(\\rho_*\\)。经济层：是否存在「真正的」瞬时相关——若价格发现有领先滞后，瞬时 \\(\\rho_*\\) 取决于你是否把滞后的信息算进同一瞬间。</p><p>配对交易常在日频上确认协整，却用盘中相关去做动态对冲。两套 \\(\\rho\\) 不一致时，盘中 \\(\\beta\\) 偏小，看起来对冲很紧，收盘后残差跳开。这不是协整破裂，是协方差对象换了频率。反之，用日频 \\(\\beta\\) 在 tick 上做市，会忽略盘中领先滞后，残差在秒级不可交易。</p><h3 id="不是「相关消失」-是估计对象被污染" tabindex="-1">不是「相关消失」，是估计对象被污染 <a class="header-anchor" href="#不是「相关消失」-是估计对象被污染" aria-label="Permalink to &quot;不是「相关消失」，是估计对象被污染&quot;">​</a></h3><p>Epps 原文用的是等间隔样本相关，同步方式接近当时能用的收盘对齐。后续文献把下降主要归因于：非同步交易（Scholes–Williams 已在日频 beta 上处理过薄交易）、买卖价差弹跳（对角线方差被噪声抬高，相关被压）、以及一期内的领先滞后被切碎。没有任何一块要求「经济相关在高频为 0」。把 Epps 图当成「高频可以忽略系统风险」是误读。指数套利、ETF 申赎、宏观公告下的共跳，都在高频存在；估计量把它们测矮了。</p><p><span class="marginnote">相关的分母是两个标准差。噪声让已实现方差在高频爆炸，即使协方差估计无偏，相关也会降。只修分子（HY）或只降频修分母，签名图都不会完全走平。要同时看已实现协方差与已实现方差两条签名图。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><strong>对照签名图。</strong> 对同一日、同一对名字，画 \\(\\Delta\\) 从 1 秒到 30 分钟的：朴素同步协方差、HY 协方差、刷新时间加核的协方差，以及各自对应的相关。若 HY 把相关从秒级抬回分钟级，主导是不同步；若 HY 之后仍低、核才抬回，主导是噪声；若任何同期估计都低、但 \\(X\\) 领先 \\(Y\\) 数秒的交叉相关高，主导是领先滞后。这张图是诊断，不是用来每天挑一个最大 \\(\\rho\\) 的 \\(\\Delta\\)——那会把搜索送进配置。</p><p><strong>频率对齐规则。</strong> 预先规定交易与风险的时钟：日频策略用隔夜加日收益的协方差；分钟再平衡用 HY 或五分钟核；做市用中点预平均。禁止用「相关最高的那个 \\(\\Delta\\)」回填历史 \\(\\beta\\)。薄交易的腿，Epps 更严重，应强制用更疏的 \\(\\Delta\\) 或 HY，而不是假装有 tick 相关。</p><p><strong>领先滞后单独建模。</strong> 期货与 ETF、ADR 与本地股、指数与成份股，经济上就不是瞬时对称。估计 \\(\\rho(\\ell)=\\mathrm{Corr}(r^X_t,r^Y_{t+\\ell})\\)，把峰值滞后写成执行延迟或信息份额，而不是强迫 HY 的零滞后等于 1。配对若一边是期货一边是股票，盘中对冲比应含滞后项，否则残差是结构的，不是 OU。</p><h3 id="离散报价与稀疏成交" tabindex="-1">离散报价与稀疏成交 <a class="header-anchor" href="#离散报价与稀疏成交" aria-label="Permalink to &quot;离散报价与稀疏成交&quot;">​</a></h3><p>价格只能落在 tick 网格上，短间隔内许多「收益」是 0 或一个 tick，相关被网格噪声主导。成交稀疏时，previous-tick 制造长串零，Epps 加速。对策是：用中点而非成交价减弹跳；用事件时间或成交量时钟，使每一步都有经济内容；对极薄的名字放弃秒级相关。A 股涨跌停使一腿方差骤降、相关无定义或伪稳定，应把触及涨跌停的间隔从签名图里剔除，否则会把制度冻结读成「高频相关很高」或「突然很低」，取决于另一腿是否同时停。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>不同步：共同的布朗增量发生在连续时间，观测是点过程。密格子里多数格只捕获一腿，乘积期望趋向 0，见 HY 一文的零填充。噪声：Roll 弹跳增加方差、短滞后负自相关；两腿噪声若不完全相关，相关下降。领先滞后：信息先进入期货或活跃股，慢的腿在下一格才动，同期 \\(\\rho(\\Delta)\\) 在 \\(\\Delta\\) 小于滞后时变小，在 \\(\\Delta\\) 覆盖滞后时回升——因此 Epps 曲线不一定单调，可能在某个中等 \\(\\Delta\\) 出现局部平台。共跳：宏观秒级上相关应升高；若你的清洗把跳跃当错单删掉，又会压低高频相关。机制可以叠加，签名图无法用单一 \\(\\Delta\\)「消除 Epps」，只能选择与问题匹配的偏差。</p><p>对均值回复策略：被压低的 \\(\\rho\\) 给出偏小的 \\(\\beta\\)，残差吸收了共同因子。全样本 OU 会把这块共同因子的慢回复当成 \\(\\kappa\\)，半衰期和阈值都错。应用与持有期同阶的收益估 \\(\\beta\\)，再用残差估 OU；高频只用于执行与盘中风险，不用于定义均衡。</p><p><span class="marginnote">Scholes–Williams 与 Dimson 的滞后 beta 是日频薄交易版本的同一直觉。Epps 把它推进到日内。不要在分钟数据上重跑一个未加不同步修正的 OLS beta，还声称比日频更「及时」。</span></p><h3 id="与协整、门限的边界" tabindex="-1">与协整、门限的边界 <a class="header-anchor" href="#与协整、门限的边界" aria-label="Permalink to &quot;与协整、门限的边界&quot;">​</a></h3><p>Epps 是协方差估计问题，不是长期均衡问题。协整关注 \\(I(1)\\) 水平的线性组合是否 \\(I(0)\\)，采样频率改变的是有限样本与噪声，不是定义。但<strong>有限样本</strong>上，用高频残差做 ADF 会被微观结构负相关推向「过度拒绝单位根」，看起来人人协整。应在日频或经噪声修正的低频残差上做 GH / EG，把高频留给协方差。门限若用 tick 估，会把买卖价差当成 \\(\\theta\\)，那是 Epps/Roll 尺度，不是 Balke–Fomby 的经济带。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>不要为了让相关「看起来像日频」就任意拉长 \\(\\Delta\\) 直到满意——那是用偏差换视觉。不要把 Epps 当 alpha：你无法靠「在相关被低估的频率上做空相关」稳定赚钱，因为你同时买了噪声方差与不同步误差。指数产品的设计（申赎篮子、期现）会在某些 \\(\\Delta\\) 上制造额外的领先滞后，签名图随制度变，2010 年的五分钟经验不能直接搬到 2026 年的 tick。</p><p>报告相关必须写：价格类型（成交/中点）、同步方法、是否含隔夜、\\(\\Delta\\) 或核带宽。否则「相关 0.3」不可比。</p><p><span class="marginnote">Epps（1979）的贡献是经验规则：短窗样本相关不可当作长窗相关的无偏观测。修正是估计量与频率选择，不是在经济模型里令 \\(\\rho(\\Delta)=\\rho_*/(1+\\lambda/\\Delta)\\) 再把 \\(\\lambda\\) 当可交易参数——除非你真的在估领先滞后结构，并且样本外稳定。</span></p>',25)),(e(),i(h,null,{default:r(()=>[n(l,{id:"mermaid-73",class:"mermaid",graph:"flowchart%20TD%0A%20%20R%5B%22%E6%A0%B7%E6%9C%AC%E7%9B%B8%E5%85%B3%20%CF%81(%CE%94)%22%5D%20--%3E%20D%5B%22%CE%94%20%E7%BC%A9%E7%9F%AD%22%5D%0A%20%20D%20--%3E%20NS%5B%22%E9%9D%9E%E5%90%8C%E6%AD%A5%E9%9B%B6%E5%A1%AB%E5%85%85%22%5D%0A%20%20D%20--%3E%20NO%5B%22%E5%99%AA%E5%A3%B0%E6%8A%AC%E9%AB%98%E6%96%B9%E5%B7%AE%22%5D%0A%20%20D%20--%3E%20LL%5B%22%E9%A2%86%E5%85%88%E6%BB%9E%E5%90%8E%E8%A2%AB%E5%88%87%E7%A2%8E%22%5D%0A%20%20NS%20--%3E%20HY%5B%22Hayashi-Yoshida%22%5D%0A%20%20NO%20--%3E%20KER%5B%22%E5%B7%B2%E5%AE%9E%E7%8E%B0%E6%A0%B8%20%2F%20%E9%A2%84%E5%B9%B3%E5%9D%87%22%5D%0A%20%20LL%20--%3E%20LAG%5B%22%E6%98%BE%E5%BC%8F%E6%BB%9E%E5%90%8E%E4%BA%A4%E5%8F%89%E7%9B%B8%E5%85%B3%22%5D%0A%20%20HY%20--%3E%20RHO%5B%22%E6%8E%A5%E8%BF%91%E7%9E%AC%E6%97%B6%E5%85%B1%E5%8F%98%E5%B7%AE%22%5D%0A%20%20KER%20--%3E%20RHO%0A%20%20LAG%20--%3E%20RHO%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Epps（1979）发现样本相关随采样间隔缩短而下降；这是高频估计签名，不是「瞬时系统风险为零」。</li><li>机制包括非同步交易、微观结构噪声抬高分母、领先滞后被过密的同期窗口切开。</li><li>Hayashi–Yoshida 修对齐；核与预平均修噪声；领先滞后要单独建模，不能靠再降频假装没有。</li><li>对冲比与 OU 残差必须在与持有期匹配的频率上定义，否则会把共同因子写成假平稳残差。</li><li>签名图用于诊断主导机制，不用于每天挑选最大相关的 \\(\\Delta\\)。</li><li>出处：Epps, <em>JASA</em>, 1979；Hayashi and Yoshida, <em>Bernoulli</em>, 2005；薄交易日频 beta 见 Scholes and Williams；已实现协方差见 Barndorff-Nielsen and Shephard。</li></ul>',2))])}const b=s(d,[["render",c]]);export{f as __pageData,b as default};
